# Picker 选择器

## 示例

## 引入

全局引入，在 miniprogram 根目录下的`app.json`中配置，局部引入，在需要引入的页面或组件的`index.json`中配置。

```json
"usingComponents": {
"t-picker": "tdesign-miniprogram/picker/picker",
"t-picker-item": "tdesign-miniprogram/picker-item/picker-item",
}
```

## 代码演示

[在开发者工具中预览效果](https://developers.weixin.qq.com/s/T7yFwMmi8O57)

> Tips: 请确保开发者工具为打开状态。导入开发者工具后，依次执行：npm i > 构建npm包 > 勾选 "将JS编译成ES5"

### 组件类型

#### 基础选择器

单项和多选选择

**WXML** (`html`):
```html
<t-cell class="mb-16" title="选择城市" arrow hover note="{{cityText}}" bind:click="onCityPicker" />

<t-cell class="mb-16" title="选择时间" arrow hover note="{{dateText}}" bind:click="onSeasonPicker" />

<t-picker
visible="{{cityVisible}}"
value="{{cityValue}}"
data-key="city"
title="选择城市"
cancelBtn="取消"
confirmBtn="确认"
usingCustomNavbar
bindchange="onPickerChange"
bindpick="onColumnChange"
bindcancel="onPickerCancel"
>
<t-picker-item options="{{citys}}" format="{{formatter}}">
<block wx:for="{{citys}}" wx:key="index" wx:for-item="option">
<view wx:if="{{option.tag}}" slot="label-suffix--{{index}}" class="label-suffix">
<t-tag size="small" theme="primary">{{option.tag}}</t-tag>
</view>
</block>
</t-picker-item>
</t-picker>

<t-picker
visible="{{dateVisible}}"
value="{{dateValue}}"
data-key="date"
title="选择时间"
cancelBtn="取消"
confirmBtn="确认"
usingCustomNavbar
bindchange="onPickerChange"
bindpick="onColumnChange"
bindcancel="onPickerCancel"
>
<t-picker-item options="{{years}}"></t-picker-item>
<t-picker-item options="{{seasons}}"></t-picker-item>
</t-picker>

```

**JS** (`javascript`):
```javascript
Component({
data: {
cityText: '',
cityValue: [],
dateText: '',
dateValue: [],
citys: [
{ label: '北京市', value: '北京市', icon: 'home', tag: '合' },
{ label: '上海市', value: '上海市', tag: '合' },
{ label: '广州市', value: '广州市' },
{ label: '深圳市', value: '深圳市' },
{ label: '成都市', value: '成都市' },
],
years: [
{ label: '2021年', value: '2021' },
{ label: '2020年', value: '2020' },
{ label: '2019年', value: '2019' },
],
seasons: [
{ label: '春', value: '春' },
{ label: '夏', value: '夏' },
{ label: '秋', value: '秋' },
{ label: '冬', value: '冬' },
],
formatter(item) {
const { value, label } = item;
if (value === '北京市') {
return {
...item,
value,
label: label.substring(0, 2),
};
}
return item;
},
},

methods: {
onColumnChange(e) {
console.log('picker pick:', e);
},

onPickerChange(e) {
const { key } = e.currentTarget.dataset;
const { value } = e.detail;

console.log('picker change:', e.detail);
this.setData({
[`${key}Visible`]: false,
[`${key}Value`]: value,
[`${key}Text`]: value.join(' '),
});
},

onPickerCancel(e) {
const { key } = e.currentTarget.dataset;
console.log(e, '取消');
console.log('picker1 cancel:');
this.setData({
[`${key}Visible`]: false,
});
},

onCityPicker() {
this.setData({ cityVisible: true });
},

onSeasonPicker() {
this.setData({ dateVisible: true });
},
},
});

```

**CSS** (`css`):
```css
.mb-16 {
margin-bottom: 32rpx;
}

.label-suffix {
--td-tag-small-height: 32rpx;

display: flex;
align-items: center;
justify-content: center;
margin-left: 12rpx;
}

```

**JSON** (`javascript`):
```javascript
{
"component": true,
"usingComponents": {
"t-cell-group": "tdesign-miniprogram/cell-group/cell-group",
"t-cell": "tdesign-miniprogram/cell/cell",
"t-picker": "tdesign-miniprogram/picker/picker",
"t-picker-item": "tdesign-miniprogram/picker-item/picker-item",
"t-tag": "tdesign-miniprogram/tag/tag"
}
}

```

